COMPENSATION_GUARDS = r"""
CREATE FUNCTION enforce_comp_configuration_child() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cyc comp_cycle;
BEGIN
    SELECT * INTO cyc FROM comp_cycle WHERE id=NEW.cycle_id FOR UPDATE;
    IF cyc.state IS DISTINCT FROM 'CONFIGURING' THEN
        RAISE EXCEPTION 'compensation configuration is sealed' USING ERRCODE='23514';
    END IF;
    IF TG_TABLE_NAME='comp_eligibility' THEN
        IF NOT (cyc.selected_ids ? NEW.employee_id) OR NEW.document->>'employee_id' IS DISTINCT FROM NEW.employee_id
            OR (NEW.document->>'eligible')::boolean IS DISTINCT FROM NEW.eligible
            OR NEW.document->>'proposer_id' IS DISTINCT FROM NEW.proposer_id THEN
            RAISE EXCEPTION 'eligibility must match selected frozen inputs' USING ERRCODE='23514';
        END IF;
        IF NEW.eligible AND NOT EXISTS (SELECT 1 FROM comp_pool p WHERE p.id=NEW.pool_id AND p.cycle_id=NEW.cycle_id
            AND p.manager_id=NEW.proposer_id AND p.org_id=NEW.document->>'org_id' AND p.currency=NEW.document->>'currency') THEN
            RAISE EXCEPTION 'eligibility requires its assigned manager pool' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.document->'history') h WHERE NOT EXISTS
            (SELECT 1 FROM employee_version e WHERE e.id=h->>'version_id' AND e.snapshot_id=cyc.snapshot_id
             AND e.employee_id=NEW.employee_id AND e.source_batch_id=h->>'source_batch_id')) THEN
            RAISE EXCEPTION 'eligibility history must belong to the pinned source' USING ERRCODE='23514';
        END IF;
    ELSE
        IF NOT (cyc.scope_orgs ? NEW.org_id) OR NEW.cost_center !~ '^[A-Za-z0-9_-]{1,20}$' THEN
            RAISE EXCEPTION 'pool requires configured organization and cost center' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_revision() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE prop comp_proposal; cyc comp_cycle;
BEGIN
    SELECT c.* INTO cyc FROM comp_cycle c JOIN comp_proposal p ON p.cycle_id=c.id WHERE p.id=NEW.proposal_id FOR UPDATE OF c;
    SELECT * INTO prop FROM comp_proposal WHERE id=NEW.proposal_id FOR UPDATE;
    IF NEW.number<>prop.current_revision+1 OR NEW.award->>'employee_id' IS DISTINCT FROM prop.employee_id
        OR NEW.award->>'merit_minor' IS DISTINCT FROM NEW.merit_minor::text
        OR NEW.award->>'bonus_target_minor' IS DISTINCT FROM NEW.bonus_minor::text THEN
        RAISE EXCEPTION 'revision must bind next number and exact award' USING ERRCODE='23514';
    END IF;
    IF NEW.kind='INITIAL' THEN
        IF prop.state<>'BUILDING' OR cyc.state<>'CONFIGURING' OR NEW.author_id<>cyc.owner_id OR NEW.merit_minor<>0 OR NEW.bonus_minor<>0 THEN
            RAISE EXCEPTION 'initial revision must be a zero award at launch' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.kind='EDIT' THEN
        IF prop.state NOT IN ('DRAFT','RETURNED') OR cyc.state NOT IN ('OPEN','REVIEWING') OR NEW.author_id<>prop.proposer_id THEN
            RAISE EXCEPTION 'edit requires an open manager draft' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.kind='RETURN' THEN
        IF prop.state<>'APPROVAL_PENDING' OR cyc.state NOT IN ('REVIEWING','FINAL_APPROVAL') OR NOT EXISTS
            (SELECT 1 FROM comp_decision d JOIN comp_proposal_revision r ON r.id=d.revision_id
             WHERE d.proposal_id=prop.id AND d.expected_version=prop.version AND d.action='RETURN'
             AND d.actor_id=NEW.author_id AND r.number=prop.current_revision) THEN
            RAISE EXCEPTION 'return requires the named current decision' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_step() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE prop comp_proposal; cyc comp_cycle; rev comp_proposal_revision; route jsonb; pool_org text;
    required_role text; required_cap text; required_actor text;
BEGIN
    SELECT c.* INTO cyc FROM comp_cycle c JOIN comp_proposal p ON p.cycle_id=c.id WHERE p.id=NEW.proposal_id FOR UPDATE OF c;
    SELECT * INTO prop FROM comp_proposal WHERE id=NEW.proposal_id FOR UPDATE;
    SELECT * INTO rev FROM comp_proposal_revision WHERE id=NEW.revision_id AND proposal_id=prop.id;
    SELECT p.org_id INTO pool_org FROM comp_pool p JOIN comp_eligibility e ON e.pool_id=p.id WHERE e.cycle_id=cyc.id AND e.employee_id=prop.employee_id;
    SELECT value INTO route FROM jsonb_array_elements(cyc.approvals) WHERE value->>'org_id'=pool_org;
    required_role := CASE NEW.ordinal WHEN 1 THEN 'DIVISION' WHEN 2 THEN 'HR' ELSE 'FINANCE' END;
    required_cap := CASE NEW.ordinal WHEN 1 THEN 'comp.approve' WHEN 2 THEN 'comp.hr.signoff' ELSE 'comp.finance.signoff' END;
    required_actor := route->>(CASE NEW.ordinal WHEN 1 THEN 'division_approver_id' WHEN 2 THEN 'hr_signoff_id' ELSE 'finance_signoff_id' END);
    IF rev.number IS DISTINCT FROM prop.current_revision+1 OR NEW.role IS DISTINCT FROM required_role
        OR NEW.capability IS DISTINCT FROM required_cap OR NEW.assigned_id IS DISTINCT FROM required_actor
        OR NEW.assigned_id=prop.proposer_id OR NEW.exception_codes IS DISTINCT FROM
            (CASE NEW.ordinal WHEN 1 THEN rev.award->'exceptions' ELSE '[]'::jsonb END) THEN
        RAISE EXCEPTION 'approval step must preserve frozen serial assignment and separation of duties' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_decision() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE prop comp_proposal; cyc comp_cycle; rev comp_proposal_revision; step comp_approval_step;
    next_step integer; expected_exceptions jsonb; pool_id text;
BEGIN
    SELECT c.* INTO cyc FROM comp_cycle c JOIN comp_proposal p ON p.cycle_id=c.id WHERE p.id=NEW.proposal_id FOR UPDATE OF c;
    SELECT * INTO prop FROM comp_proposal WHERE id=NEW.proposal_id FOR UPDATE;
    SELECT * INTO rev FROM comp_proposal_revision WHERE proposal_id=prop.id AND number=prop.current_revision;
    IF NEW.expected_version<>prop.version OR NEW.revision_id<>rev.id THEN
        RAISE EXCEPTION 'decision requires current proposal revision and version' USING ERRCODE='23514';
    END IF;
    IF NEW.action='SUBMIT' THEN
        IF prop.state<>'DRAFT' OR cyc.state NOT IN ('OPEN','REVIEWING') OR NEW.actor_id<>prop.proposer_id OR NEW.ordinal<>0 OR NEW.round_id IS NOT NULL
            OR jsonb_array_length(rev.award->'blockers')<>0 OR length(btrim(rev.comment))<3
            OR NOT EXISTS (SELECT 1 FROM comp_revision_verification v WHERE v.revision_id=rev.id AND v.sha256=rev.sha256) THEN
            RAISE EXCEPTION 'submission requires a verified valid manager proposal' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.action='INVALIDATE_FINANCE' THEN
        IF prop.state<>'APPROVED' OR cyc.state<>'REVIEWING' OR cyc.current_round_id IS NOT NULL OR NEW.ordinal<>3 OR NOT EXISTS
            (SELECT 1 FROM comp_cycle_action a WHERE a.cycle_id=cyc.id AND a.expected_version=cyc.version-1
             AND a.action='RETURN_TO_REVIEW' AND a.actor_id=NEW.actor_id) THEN
            RAISE EXCEPTION 'finance invalidation requires the explicit cycle return' USING ERRCODE='23514';
        END IF;
    ELSE
        SELECT * INTO step FROM comp_approval_step WHERE revision_id=rev.id AND ordinal=NEW.ordinal;
        IF step.assigned_id IS DISTINCT FROM NEW.actor_id OR NEW.actor_id=prop.proposer_id THEN
            RAISE EXCEPTION 'only the named separate reviewer may decide' USING ERRCODE='23514';
        END IF;
        IF NEW.action='START_REVIEW' THEN
            IF prop.state<>'SUBMITTED' OR NEW.ordinal<>1 OR cyc.state<>'REVIEWING' OR NEW.round_id IS NOT NULL THEN
                RAISE EXCEPTION 'review starts with the assigned division reviewer' USING ERRCODE='23514';
            END IF;
        ELSE
            SELECT min(s.ordinal) INTO next_step FROM comp_approval_step s WHERE s.revision_id=rev.id AND NOT EXISTS
                (SELECT 1 FROM comp_decision d WHERE d.revision_id=rev.id AND d.ordinal=s.ordinal AND d.action='APPROVE'
                 AND (s.ordinal<>3 OR d.round_id=cyc.current_round_id));
            IF prop.state<>'APPROVAL_PENDING' OR NEW.ordinal IS DISTINCT FROM next_step OR
                (NEW.ordinal=3 AND (cyc.state<>'FINAL_APPROVAL' OR NEW.round_id IS DISTINCT FROM cyc.current_round_id)) OR
                (NEW.ordinal<>3 AND (cyc.state<>'REVIEWING' OR NEW.round_id IS NOT NULL)) THEN
                RAISE EXCEPTION 'serial approval cannot skip or use a stale round' USING ERRCODE='23514';
            END IF;
            expected_exceptions := step.exception_codes;
            IF NEW.ordinal=3 THEN
                SELECT e.pool_id INTO pool_id FROM comp_eligibility e WHERE e.cycle_id=cyc.id AND e.employee_id=prop.employee_id;
                SELECT value->'exceptions' INTO expected_exceptions FROM comp_review_round r,
                    jsonb_array_elements(r.document->'pools') WHERE r.id=cyc.current_round_id AND value->>'id'=pool_id;
            END IF;
            IF NEW.action='APPROVE' AND NEW.acknowledged_exceptions IS DISTINCT FROM expected_exceptions THEN
                RAISE EXCEPTION 'named reviewer must explicitly acknowledge exact exceptions' USING ERRCODE='23514';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_proposal() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cyc comp_cycle; elig comp_eligibility; rev comp_proposal_revision; decision comp_decision; expected_state text;
BEGIN
    SELECT * INTO cyc FROM comp_cycle WHERE id=NEW.cycle_id FOR UPDATE;
    IF TG_OP='INSERT' THEN
        SELECT * INTO elig FROM comp_eligibility WHERE cycle_id=cyc.id AND employee_id=NEW.employee_id;
        IF cyc.state<>'CONFIGURING' OR NOT elig.eligible OR NEW.proposer_id IS DISTINCT FROM elig.proposer_id OR NEW.state<>'BUILDING' OR NEW.version<>0 OR NEW.current_revision<>0 THEN
            RAISE EXCEPTION 'proposal must originate from launch eligibility' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.state='LOCKED' OR NEW.version<>OLD.version+1 OR
        (to_jsonb(NEW)-ARRAY['state','version','current_revision']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','version','current_revision']) THEN
        RAISE EXCEPTION 'proposal pins are immutable and versions advance once' USING ERRCODE='23514';
    END IF;
    IF NEW.current_revision=OLD.current_revision+1 THEN
        SELECT * INTO rev FROM comp_proposal_revision WHERE proposal_id=OLD.id AND number=NEW.current_revision;
        expected_state := CASE rev.kind WHEN 'RETURN' THEN 'RETURNED' ELSE 'DRAFT' END;
        IF NEW.state IS DISTINCT FROM expected_state OR (SELECT count(*) FROM comp_approval_step WHERE revision_id=rev.id)<>3 THEN
            RAISE EXCEPTION 'proposal head needs a complete revision and route' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.current_revision=OLD.current_revision THEN
        IF NEW.state='LOCKED' THEN
            IF OLD.state<>'APPROVED' OR cyc.state<>'LOCKED' OR NOT EXISTS (SELECT 1 FROM comp_lock WHERE cycle_id=cyc.id) THEN
                RAISE EXCEPTION 'proposal locking requires finalized cycle evidence' USING ERRCODE='23514';
            END IF;
        ELSE
            SELECT * INTO decision FROM comp_decision WHERE proposal_id=OLD.id AND expected_version=OLD.version;
            expected_state := CASE decision.action WHEN 'SUBMIT' THEN 'SUBMITTED' WHEN 'INVALIDATE_FINANCE' THEN 'APPROVAL_PENDING'
                WHEN 'START_REVIEW' THEN 'APPROVAL_PENDING' WHEN 'APPROVE' THEN CASE decision.ordinal WHEN 3 THEN 'APPROVED' ELSE 'APPROVAL_PENDING' END END;
            IF NEW.state IS DISTINCT FROM expected_state THEN
                RAISE EXCEPTION 'proposal transition needs its durable decision' USING ERRCODE='23514';
            END IF;
        END IF;
    ELSE
        RAISE EXCEPTION 'revision cannot jump or roll back' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_round() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cyc comp_cycle;
BEGIN
    SELECT * INTO cyc FROM comp_cycle WHERE id=NEW.cycle_id FOR UPDATE;
    IF cyc.state<>'REVIEWING' OR NEW.number<>(SELECT count(*)+1 FROM comp_review_round WHERE cycle_id=cyc.id) OR
        jsonb_array_length(NEW.document->'proposal_revisions')<>(SELECT count(*) FROM comp_proposal WHERE cycle_id=cyc.id) OR EXISTS
        (SELECT 1 FROM comp_proposal p JOIN comp_proposal_revision r ON r.proposal_id=p.id AND r.number=p.current_revision
         WHERE p.cycle_id=cyc.id AND (p.state<>'APPROVAL_PENDING' OR NOT EXISTS
            (SELECT 1 FROM comp_decision d WHERE d.revision_id=r.id AND d.ordinal=2 AND d.action='APPROVE') OR NOT EXISTS
            (SELECT 1 FROM jsonb_array_elements(NEW.document->'proposal_revisions') v WHERE v->>'proposal_id'=p.id AND v->>'revision_id'=r.id AND v->>'revision_sha256'=r.sha256))) THEN
        RAISE EXCEPTION 'finance round must freeze every current HR-approved revision' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_cycle_action() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cyc comp_cycle;
BEGIN
    SELECT * INTO cyc FROM comp_cycle WHERE id=NEW.cycle_id FOR UPDATE;
    IF NEW.expected_version IS DISTINCT FROM cyc.version THEN
        RAISE EXCEPTION 'cycle action requires its current version' USING ERRCODE='23514';
    END IF;
    IF NEW.action IN ('LAUNCH','LOCK','RECONCILE','RETRY_EXPORT','CANCEL') AND NEW.actor_id IS DISTINCT FROM cyc.owner_id THEN
        RAISE EXCEPTION 'only the assigned cycle controller may finalize' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_cycle() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE act comp_cycle_action; expected_state text;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'CONFIGURING' OR NEW.version<>1 OR NEW.current_round_id IS NOT NULL OR NOT EXISTS
            (SELECT 1 FROM snapshot WHERE id=NEW.snapshot_id AND status='PUBLISHED') OR NOT EXISTS
            (SELECT 1 FROM fx_rate_set WHERE id=NEW.fx_set_id AND state='SEALED') OR jsonb_array_length(NEW.selected_ids) NOT BETWEEN 1 AND 5000 THEN
            RAISE EXCEPTION 'cycle requires published source and explicit bounded configuration' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.state IN ('RECONCILED','CANCELLED') OR NEW.version<>OLD.version+1 OR
        (to_jsonb(NEW)-ARRAY['state','version','current_round_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','version','current_round_id']) THEN
        RAISE EXCEPTION 'cycle pins are immutable and versions advance once' USING ERRCODE='23514';
    END IF;
    SELECT * INTO act FROM comp_cycle_action WHERE cycle_id=OLD.id AND expected_version=OLD.version;
    expected_state := CASE act.action WHEN 'LAUNCH' THEN CASE OLD.state WHEN 'CONFIGURING' THEN 'OPEN' END
        WHEN 'REVIEWING' THEN CASE OLD.state WHEN 'OPEN' THEN 'REVIEWING' END
        WHEN 'OPEN_FINANCE' THEN CASE OLD.state WHEN 'REVIEWING' THEN 'FINAL_APPROVAL' END
        WHEN 'RETURN_TO_REVIEW' THEN CASE OLD.state WHEN 'FINAL_APPROVAL' THEN 'REVIEWING' END
        WHEN 'LOCK' THEN CASE OLD.state WHEN 'FINAL_APPROVAL' THEN 'LOCKED' END
        WHEN 'EXPORTED' THEN CASE OLD.state WHEN 'LOCKED' THEN 'EXPORTED' END
        WHEN 'RECONCILE' THEN CASE OLD.state WHEN 'EXPORTED' THEN 'RECONCILED' END
        WHEN 'FAILED_EXPORT' THEN CASE OLD.state WHEN 'LOCKED' THEN 'FAILED_EXPORT' END
        WHEN 'RETRY_EXPORT' THEN CASE OLD.state WHEN 'FAILED_EXPORT' THEN 'LOCKED' END
        WHEN 'CANCEL' THEN CASE OLD.state WHEN 'CONFIGURING' THEN 'CANCELLED' END END;
    IF NEW.state IS DISTINCT FROM expected_state OR expected_state IS NULL THEN
        RAISE EXCEPTION 'cycle transition requires its explicit durable action' USING ERRCODE='23514';
    END IF;
    IF act.action='LAUNCH' THEN
        IF (SELECT count(*) FROM comp_eligibility WHERE cycle_id=OLD.id)<>jsonb_array_length(OLD.selected_ids)
            OR (SELECT count(*) FROM comp_proposal WHERE cycle_id=OLD.id)=0 OR
            (SELECT count(*) FROM comp_proposal WHERE cycle_id=OLD.id)<>(SELECT count(*) FROM comp_eligibility WHERE cycle_id=OLD.id AND eligible)
            OR EXISTS (SELECT 1 FROM comp_proposal WHERE cycle_id=OLD.id AND (state<>'DRAFT' OR current_revision<>1 OR version<>1)) THEN
            RAISE EXCEPTION 'launch must freeze every eligibility and complete draft' USING ERRCODE='23514';
        END IF;
    END IF;
    IF act.action='OPEN_FINANCE' THEN
        IF NOT EXISTS (SELECT 1 FROM comp_review_round WHERE id=NEW.current_round_id AND cycle_id=OLD.id AND sha256=act.evidence_sha256) THEN
            RAISE EXCEPTION 'finance requires exact frozen round' USING ERRCODE='23514';
        END IF;
    ELSIF act.action='RETURN_TO_REVIEW' THEN
        IF NEW.current_round_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM comp_decision d JOIN comp_proposal p ON p.id=d.proposal_id
            WHERE p.cycle_id=OLD.id AND d.action='RETURN' AND d.ordinal=3 AND d.round_id=OLD.current_round_id AND d.actor_id=act.actor_id) THEN
            RAISE EXCEPTION 'finance return requires current separate decision' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.current_round_id IS DISTINCT FROM OLD.current_round_id THEN
        RAISE EXCEPTION 'round pointer changes only through finance transitions' USING ERRCODE='23514';
    END IF;
    IF act.action='LOCK' THEN
        IF OLD.current_round_id IS NULL OR NOT EXISTS (SELECT 1 FROM comp_lock WHERE cycle_id=OLD.id AND sha256=act.evidence_sha256) OR EXISTS
            (SELECT 1 FROM comp_proposal p JOIN comp_proposal_revision r ON r.proposal_id=p.id AND r.number=p.current_revision
             WHERE p.cycle_id=OLD.id AND (p.state<>'APPROVED' OR NOT EXISTS
                (SELECT 1 FROM comp_decision d WHERE d.revision_id=r.id AND d.ordinal=3 AND d.action='APPROVE' AND d.round_id=OLD.current_round_id))) THEN
            RAISE EXCEPTION 'locking requires every current Finance signature' USING ERRCODE='23514';
        END IF;
    ELSIF act.action='EXPORTED' THEN
        IF NOT EXISTS (SELECT 1 FROM comp_export_artifact WHERE cycle_id=OLD.id AND sha256=act.evidence_sha256) THEN
            RAISE EXCEPTION 'export transition requires counted artifact' USING ERRCODE='23514';
        END IF;
    ELSIF act.action='RECONCILE' THEN
        IF NOT EXISTS (SELECT 1 FROM comp_reconciliation WHERE cycle_id=OLD.id AND export_sha256=act.evidence_sha256) THEN
            RAISE EXCEPTION 'reconciliation requires immutable result' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END; $$;

CREATE FUNCTION enforce_comp_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cyc comp_cycle; rev comp_proposal_revision;
BEGIN
    IF TG_TABLE_NAME='comp_revision_verification' THEN
        SELECT * INTO rev FROM comp_proposal_revision WHERE id=NEW.revision_id;
        IF NEW.sha256 IS DISTINCT FROM rev.sha256 THEN
            RAISE EXCEPTION 'verification must match exact financial revision' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO cyc FROM comp_cycle WHERE id=NEW.cycle_id FOR UPDATE;
    IF TG_TABLE_NAME='comp_lock' THEN
        IF cyc.state<>'FINAL_APPROVAL' OR NEW.round_id IS DISTINCT FROM cyc.current_round_id OR NOT EXISTS
            (SELECT 1 FROM comp_cycle_action WHERE id=NEW.action_id AND cycle_id=cyc.id AND action='LOCK' AND expected_version=cyc.version AND evidence_sha256=NEW.sha256) THEN
            RAISE EXCEPTION 'lock evidence requires current controller action' USING ERRCODE='23514';
        END IF;
    ELSIF TG_TABLE_NAME='comp_export_artifact' THEN
        IF cyc.state<>'LOCKED' OR NEW.version<>1 OR NOT EXISTS (SELECT 1 FROM comp_lock WHERE id=NEW.lock_id AND cycle_id=cyc.id)
            OR NEW.row_count<>(SELECT count(*) FROM comp_proposal WHERE cycle_id=cyc.id AND state='LOCKED') THEN
            RAISE EXCEPTION 'artifact requires exact locked population' USING ERRCODE='23514';
        END IF;
    ELSIF TG_TABLE_NAME='comp_reconciliation' THEN
        IF cyc.state<>'EXPORTED' OR NOT EXISTS (SELECT 1 FROM comp_export_artifact WHERE cycle_id=cyc.id AND sha256=NEW.export_sha256) THEN
            RAISE EXCEPTION 'reconciliation requires current export' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END; $$;

CREATE TRIGGER comp_cycle_guard BEFORE INSERT OR UPDATE OR DELETE ON comp_cycle FOR EACH ROW EXECUTE FUNCTION enforce_comp_cycle();
CREATE TRIGGER comp_proposal_guard BEFORE INSERT OR UPDATE OR DELETE ON comp_proposal FOR EACH ROW EXECUTE FUNCTION enforce_comp_proposal();
CREATE TRIGGER comp_pool_guard BEFORE INSERT ON comp_pool FOR EACH ROW EXECUTE FUNCTION enforce_comp_configuration_child();
CREATE TRIGGER comp_eligibility_guard BEFORE INSERT ON comp_eligibility FOR EACH ROW EXECUTE FUNCTION enforce_comp_configuration_child();
CREATE TRIGGER comp_proposal_revision_guard BEFORE INSERT ON comp_proposal_revision FOR EACH ROW EXECUTE FUNCTION enforce_comp_revision();
CREATE TRIGGER comp_approval_step_guard BEFORE INSERT ON comp_approval_step FOR EACH ROW EXECUTE FUNCTION enforce_comp_step();
CREATE TRIGGER comp_decision_guard BEFORE INSERT ON comp_decision FOR EACH ROW EXECUTE FUNCTION enforce_comp_decision();
CREATE TRIGGER comp_review_round_guard BEFORE INSERT ON comp_review_round FOR EACH ROW EXECUTE FUNCTION enforce_comp_round();
CREATE TRIGGER comp_cycle_action_guard BEFORE INSERT ON comp_cycle_action FOR EACH ROW EXECUTE FUNCTION enforce_comp_cycle_action();
CREATE TRIGGER comp_revision_verification_guard BEFORE INSERT ON comp_revision_verification FOR EACH ROW EXECUTE FUNCTION enforce_comp_evidence();
CREATE TRIGGER comp_lock_guard BEFORE INSERT ON comp_lock FOR EACH ROW EXECUTE FUNCTION enforce_comp_evidence();
CREATE TRIGGER comp_export_artifact_guard BEFORE INSERT ON comp_export_artifact FOR EACH ROW EXECUTE FUNCTION enforce_comp_evidence();
CREATE TRIGGER comp_reconciliation_guard BEFORE INSERT ON comp_reconciliation FOR EACH ROW EXECUTE FUNCTION enforce_comp_evidence();
"""
